'use client';
import {useCallback,useEffect,useMemo,useState,useRef} from 'react';
import Link from 'next/link';
import {useRouter} from 'next/navigation';
import {motion,AnimatePresence} from 'framer-motion';
import {Home,CheckSquare,UserRound,Trophy,CalendarDays,Settings as SettingsIcon,Plus,Search,Gift,Flame,Star,BookOpen,Heart,Wallet,Briefcase,Users,Sparkles,Trash2,Edit3,Check,Clock,ChevronLeft,ChevronRight,Download,Upload,BarChart3,Swords,Package,ArrowUpCircle,Bell, X,ShieldCheck,Target,CalendarPlus,Volume2,Medal,Save,MoonStar,RotateCcw,CloudUpload} from 'lucide-react';
import {State,Quest,QuestKind,Category,Difficulty,Priority,CalendarEvent,PrayerName,PrayerStatus,categories,difficultyLabels,priorityLabels,kindLabels,xpByDifficulty,titles} from '@/lib/types';
import {uid,localDate,dayOffset,weekStart,monthStart,progress,totalXP,skillXP,completionFor,dueToday,streaks,checkAchievements,achievements,createInitial,completeQuest,claimReward,safeState,countOn,prayers,setPrayer} from '@/lib/engine';
import {loadCloud,saveCloud,authenticate,getSession,logout,mergeStates} from '@/lib/cloud';
import {CITIES,CityKey,Schedule,uzDate,uzTimestamp,isoDayOffset,prayerWindow,currentPrayer,timeLeft,autoMarkMissed} from '@/lib/prayer-times';
const nav=[{id:'home',label:'Bosh sahifa',Icon:Home},{id:'quests',label:'Vazifalar',Icon:CheckSquare},{id:'character',label:'Qahramon',Icon:UserRound},{id:'prayer',label:'Namoz',Icon:MoonStar},{id:'achievements',label:'Yutuqlar',Icon:Trophy},{id:'calendar',label:'Taqvim',Icon:CalendarDays}];
const extras=[{id:'skills',label:'Ko‘nikmalar',Icon:Swords},{id:'inventory',label:'Xazina',Icon:Package},{id:'statistics',label:'Statistika',Icon:BarChart3},{id:'settings',label:'Sozlamalar',Icon:SettingsIcon}];
const categoryIcon:Record<Category,typeof BookOpen>={bilim:BookOpen,sogliq:Heart,rivojlanish:Sparkles,moliya:Wallet,ijtimoiy:Users,ish:Briefcase};
const fmt=(date:string)=>{if(!date)return 'Muddat yo‘q';const [y,m,d]=date.split('-');return `${d}.${m}.${y}`};
const pct=(a:number,b:number)=>b?Math.round(a/b*100):0;
const initials=(name:string)=>name.trim().slice(0,2).toUpperCase();
// Salovat matnlari — har mahal uchun boshqacha iltijo; majburiy o‘qish sharti emas.
const salawatByPrayer:Record<PrayerName,{title:string;arabic:string;latin:string;meaning:string}>={
 bomdod:{title:'Tong salovati',arabic:'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ',latin:'Allohumma solli ‘ala Muhammad va ‘ala oli Muhammad.',meaning:'Allohim, Muhammadga va u zotning oilalariga salovat yo‘lla.'},
 peshin:{title:'Baraka salovati',arabic:'اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ',latin:'Allohumma barik ‘ala Muhammad va ‘ala oli Muhammad.',meaning:'Allohim, Muhammadga va u zotning oilalariga baraka ato et.'},
 asr:{title:'Salom salovati',arabic:'اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ',latin:'Allohumma solli va sallim ‘ala nabiyyina Muhammad.',meaning:'Allohim, payg‘ambarimiz Muhammadga salovat va salom yo‘lla.'},
 shom:{title:'Salovat va salom',arabic:'صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ',latin:'Sallallohu ‘alayhi vasallam.',meaning:'U zotga Allohning salovati va salomi bo‘lsin.'},
 xufton:{title:'Kechki salovat',arabic:'اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ',latin:'Allohumma solli va sallim ‘ala Muhammad va ‘ala oli Muhammad.',meaning:'Allohim, Muhammadga va u zotning oilalariga salovat va salom yo‘lla.'},
};
const countdownText=(target:number,now:number)=>{const seconds=Math.max(0,Math.ceil((target-now)/1000));return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor((seconds%3600)/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`};
const blankQuest=(date=localDate()):Quest=>({id:uid(),title:'',description:'',kind:'daily',category:'rivojlanish',difficulty:'medium',priority:'normal',xp:25,due:date,repeat:false,created:new Date().toISOString(),updated:new Date().toISOString()});
function Ring({value,size=100,label}:{value:number;size?:number;label?:string}){return <div className="ring" style={{width:size,height:size,background:`conic-gradient(#00E5FF ${Math.min(100,value)}%,#1b3049 0)`}}><div className="ring-inner"><strong>{Math.round(value)}%</strong>{label&&<small>{label}</small>}</div></div>}
function IconButton({onClick,children,title}:{onClick:()=>void;children:React.ReactNode;title:string}){return <button className="icon-btn" onClick={onClick} title={title} aria-label={title}>{children}</button>}
function Stat({icon:Icon,label,value,color='#00E5FF'}:{icon:typeof Home;label:string;value:string|number;color?:string}){return <div className="stat panel"><Icon size={20} style={{color}}/><strong>{value}</strong><span>{label}</span></div>}
function CardHeading({children,action}:{children:React.ReactNode;action?:React.ReactNode}){return <div className="section-head"><h2>{children}</h2>{action}</div>}
function Empty({text}:{text:string}){return <div className="empty"><Sparkles size={30}/><p>{text}</p></div>}
export default function Workspace({section}:{section:string}){
 const router=useRouter();const [state,setState]=useState<State>(createInitial);const [ready,setReady]=useState(false);const [error,setError]=useState('');const [toast,setToast]=useState('');const [editor,setEditor]=useState<Quest|null>(null);const [search,setSearch]=useState('');const [filter,setFilter]=useState('all');const [categoryFilter,setCategoryFilter]=useState('all');const [difficultyFilter,setDifficultyFilter]=useState('all');const [selectedDate,setSelectedDate]=useState(localDate());const [calendarMode,setCalendarMode]=useState<'month'|'week'>('month');const [eventEditor,setEventEditor]=useState(false);const [eventTitle,setEventTitle]=useState('');const [eventDetails,setEventDetails]=useState('');const [showNotifications,setShowNotifications]=useState(false);const [importMode,setImportMode]=useState(false);const [authenticated,setAuthenticated]=useState(false);const [authMode,setAuthMode]=useState<'login'|'register'>('login');const [authName,setAuthName]=useState('');const [authEmail,setAuthEmail]=useState('');const [authPassword,setAuthPassword]=useState('');const [loggingIn,setLoggingIn]=useState(false);const [checkingSession,setCheckingSession]=useState(true);const skipInitialSave=useRef(true);const [saveStatus,setSaveStatus]=useState<'saved'|'saving'|'error'>('saved');const [saveError,setSaveError]=useState('');const pendingState=useRef<State|null>(null);
 const [salawatTarget,setSalawatTarget]=useState<{date:string;prayer:PrayerName;kind:'completed'|'madeup'}|null>(null);const [clock,setClock]=useState(()=>Date.now());const [schedule,setSchedule]=useState<Schedule>({});const [scheduleError,setScheduleError]=useState('');const [scheduleLoading,setScheduleLoading]=useState(false);const [chosenCity,setChosenCity]=useState<CityKey>('tashkent');
 const activeCity=(state.prayerConfig?.city&&state.prayerConfig.city in CITIES?state.prayerConfig.city:chosenCity) as CityKey;
 const prayerToday=uzDate(new Date(clock));const prayerStatus=currentPrayer(schedule,clock);

 const today=localDate();const xp=totalXP(state);const lvl=progress(xp);const streak=streaks(state);const unlocked=checkAchievements(state);const achievementCount=unlocked.filter(Boolean).length;
 const notify=(message:string)=>{setToast(message);};
 useEffect(()=>{let active=true;
  getSession().then(()=>loadCloud()).then(loaded=>{if(active){skipInitialSave.current=true;setState(loaded);setAuthenticated(true);setReady(true);setCheckingSession(false);}}).catch(e=>{if(active){if(e.status===401){setAuthenticated(false);setError('')}else setError(e.message);setCheckingSession(false);}});
  if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
  return()=>{active=false};},[]);
 useEffect(()=>{if(!ready||!authenticated)return;
  if(skipInitialSave.current){skipInitialSave.current=false;return;}
  const snapshot=state;
  pendingState.current=snapshot;setSaveStatus('saving');setSaveError('');
  saveCloud(snapshot).then(saved=>{
   // Merge remote changes into the live UI, preserving edits made while request was in flight.
   setState(current=>{
    if(JSON.stringify(saved)===JSON.stringify(snapshot))return current;
    const merged=mergeStates(snapshot,current,saved);
    if(JSON.stringify(merged)===JSON.stringify(current))return current;
    if(current===snapshot)skipInitialSave.current=true;
    return merged;
   });
   if(pendingState.current===snapshot){setSaveStatus('saved');setSaveError('')}
  }).catch(e=>{
   if((e as Error&{status?:number}).status===401){setReady(false);setAuthenticated(false);return}
   if(pendingState.current===snapshot){setSaveStatus('error');setSaveError(e.message)}
  });
 },[state,ready,authenticated]);
 // Only update the clock while open. On reopen, refresh prayer schedules and catch up overdue entries.
 useEffect(()=>{const id=window.setInterval(()=>setClock(Date.now()),1000);return()=>window.clearInterval(id)},[]);
 useEffect(()=>{
  if(!ready||!authenticated)return;
  let cancelled=false;
  setSchedule({});setScheduleError('');setScheduleLoading(true);
  const date=uzDate();const monthStart=`${date.slice(0,7)}-01`;const months=[date.slice(0,7),isoDayOffset(monthStart,-1).slice(0,7),new Date(Date.parse(`${monthStart}T00:00:00Z`)+35*86400000).toISOString().slice(0,7)];
  Promise.all([...new Set(months)].map(async month=>{
   const response=await fetch(`/api/prayer-times?city=${encodeURIComponent(activeCity)}&month=${month}`,{cache:'no-store'});
   const json=await response.json();if(!response.ok)throw new Error(json.error||'Namoz jadvali olinmadi');return json.days as Array<{date:string}>;
  })).then(groups=>{if(cancelled)return;const byDate:Schedule={};for(const group of groups)for(const day of group)byDate[day.date]=day as Schedule[string];setSchedule(byDate);setScheduleError('');}).catch(e=>{if(!cancelled){setScheduleError((e as Error).message);setSchedule({})}}).finally(()=>{if(!cancelled)setScheduleLoading(false)});
  return()=>{cancelled=true};
 },[ready,authenticated,activeCity]);
 useEffect(()=>{
  if(!ready||!authenticated||!state.prayerConfig?.enabledAt||!schedule[prayerToday])return;
  const updated=autoMarkMissed(state,schedule,clock);
  if(updated!==state)setState(current=>autoMarkMissed(current,schedule,clock));
 },[ready,authenticated,clock,schedule,state,prayerToday]);
 const retrySave=()=>{if(!authenticated)return;setSaveStatus('saving');saveCloud(state).then(saved=>{
  setState(current=>{const merged=mergeStates(state,current,saved);if(JSON.stringify(merged)===JSON.stringify(current))return current;if(current===state)skipInitialSave.current=true;return merged});setSaveStatus('saved');setSaveError('');
 }).catch(e=>{setSaveStatus('error');setSaveError(e.message)});};
 const login=async(e:React.FormEvent)=>{e.preventDefault();
  setLoggingIn(true);setError('');
  try{await authenticate(authMode,authEmail,authPassword,authName);const loaded=await loadCloud();setAuthenticated(true);skipInitialSave.current=true;setState(loaded);setReady(true);setAuthPassword('');}
  catch(e){setError((e as Error).message)}finally{setLoggingIn(false)};
 };
 const signOut=async()=>{setError('');try{await logout();setAuthenticated(false);setReady(false);setState(createInitial());skipInitialSave.current=true;setAuthPassword('');location.reload()}catch(e){notify((e as Error).message)}};
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3300);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!ready||!state.settings.notifications||!('Notification'in window))return;const overdue=state.quests.filter(q=>!q.archived&&q.due&&q.due<today&&!completionFor(state,q));if(overdue.length&&Notification.permission==='granted'){new Notification('LIFEQUEST',{body:`${overdue.length} ta vazifa muddati o‘tgan`})}},[ready,state.settings.notifications,today]);
 const mutate=(fn:(prev:State)=>State)=>setState(prev=>fn(prev));
 const doComplete=(q:Quest,date=today)=>{if(date!==today){notify('Vazifani faqat bugungi sanada bajarish mumkin');return}if(completionFor(state,q,date))return;const oldLevel=levelFrom(xp);mutate(s=>completeQuest(s,q.id,date));notify(`+${q.xp} XP! «${q.title}» bajarildi${levelFrom(xp+q.xp)>oldLevel?' — Daraja oshdi!':''}`)};
 const removeQuest=(q:Quest)=>{if(!confirm(`«${q.title}» vazifasini o‘chirasizmi? Bajarilish tarixi saqlanadi.`))return;mutate(s=>({...s,quests:s.quests.filter(t=>t.id!==q.id)}));notify('Vazifa o‘chirildi')};
 const saveQuest=(q:Quest)=>{if(!q.title.trim()){notify('Vazifa nomini kiriting');return}mutate(s=>({...s,quests:s.quests.some(t=>t.id===q.id)?s.quests.map(t=>t.id===q.id?{...q,updated:new Date().toISOString()}:t):[...s.quests,q]}));setEditor(null);notify('Vazifa saqlandi')};
 const todayQuests=state.quests.filter(q=>dueToday(q,today));const todayComplete=todayQuests.filter(q=>completionFor(state,q,today)).length;
 const currentTitle=titles[Math.min(titles.length-1,Math.floor((lvl.level-1)/5))];
 const exportData=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`lifequest-zaxira-${today}.json`;a.click();URL.revokeObjectURL(url);notify('Zaxira fayli yuklandi')};
 const importData=async(file?:File)=>{if(!file)return;try{const parsed=safeState(JSON.parse(await file.text()));if(!confirm('Mavjud ma’lumot o‘rniga zaxirani tiklaysizmi?'))return;setState(parsed);setImportMode(false);notify('Ma’lumot tiklandi')}catch(e){notify((e as Error).message)}};
 const SectionTitle=({children,subtitle}:{children:React.ReactNode;subtitle?:string})=><div className="page-title"><div className="eyebrow"><Sparkles size={14}/> LIFEQUEST / SARGUZASHT</div><h1>{children}</h1>{subtitle&&<p>{subtitle}</p>}</div>;
 const QuestRow=({q,date=today}:{q:Quest;date?:string})=>{const done=completionFor(state,q,date),cat=categories.find(c=>c.id===q.category)!;return <motion.div layout className={`quest-row ${done?'done':''}`} key={q.id}><button className={`check-button ${done?'checked':''}`} onClick={()=>doComplete(q,date)} disabled={done} aria-label="Bajarildi deb belgilash">{done&&<Check size={17}/>}</button><div className="quest-content"><strong>{q.title}</strong><div className="meta"><span style={{color:cat.color}}>{cat.label}</span><span>{difficultyLabels[q.difficulty]}</span><span>{kindLabels[q.kind]}</span>{q.due&&<span><Clock size={12}/> {fmt(q.due)}</span>}</div>{q.description&&<p className="description">{q.description}</p>}</div><div className="quest-actions"><span className="xp-chip">+{q.xp} XP</span><IconButton title="Tahrirlash" onClick={()=>setEditor({...q})}><Edit3 size={16}/></IconButton><IconButton title="O‘chirish" onClick={()=>removeQuest(q)}><Trash2 size={16}/></IconButton></div></motion.div>};
 const dashboard=()=>{const start=weekStart(today);const weekDone=state.completions.filter(c=>c.date>=start&&c.date<=dayOffset(start,6)).length;const monthDone=state.completions.filter(c=>c.date.slice(0,7)===today.slice(0,7)).length;const weekPlanned=state.quests.filter(q=>q.due>=start&&q.due<=dayOffset(start,6)).length;const monthPlanned=state.quests.filter(q=>q.due.slice(0,7)===today.slice(0,7)).length;return <><SectionTitle subtitle="Har bir kichik qadam — katta g‘alabaga yo‘l.">Sarguzashtga xush kelibsiz</SectionTitle><div className="hero panel glow"><div className="hero-avatar">{state.profile.avatar.startsWith('data:')?<img src={state.profile.avatar} alt="Qahramon rasmi"/>:<span>{state.profile.avatar}</span>}</div><div className="hero-details"><span className="eyebrow">SIZNING QAHRAMONINGIZ</span><h2>{state.profile.name}</h2><p><Trophy size={15}/> {lvl.level}-daraja · {currentTitle}</p><div className="bar"><div style={{width:`${lvl.percent}%`}}/></div><small>{lvl.current} / {lvl.need} XP · Keyingi darajagacha {lvl.remaining} XP</small></div><Link href="/settings" className="hero-settings" aria-label="Sozlamalar"><SettingsIcon size={20}/></Link></div><div className="stat-grid"><Stat icon={CheckSquare} label="Bajarilgan vazifalar" value={state.completions.length}/><Stat icon={Flame} label="Kunlik seriya" value={`${streak.current} kun`} color="#FBBF24"/><Stat icon={Trophy} label="Yutuqlar" value={achievementCount} color="#A855F7"/><Stat icon={Star} label="Jami XP" value={xp.toLocaleString()} color="#22C55E"/></div><div className="two-col"><section className="panel padded"><CardHeading action={<button className="text-action" onClick={()=>setEditor(blankQuest())}><Plus size={15}/> Yangi vazifa</button>}>Bugungi kvestlar</CardHeading><p className="muted small">{todayComplete} / {todayQuests.length} ta bajarildi</p><div className="bar compact"><div style={{width:`${pct(todayComplete,todayQuests.length)}%`}}/></div>{todayQuests.length?todayQuests.map(q=><QuestRow key={q.id} q={q}/>):<Empty text="Bugun uchun vazifa yo‘q. Yangi kvest yarating!"/>}<Link className="secondary-btn full" href="/quests">Barcha vazifalar <ChevronRight size={16}/></Link></section><section className="panel padded reward-panel"><CardHeading>Kunlik sovg‘a</CardHeading><div className="reward-art"><Gift size={56}/></div><h3>Bugungi mukofotingiz</h3><p>Har kuni kirib +15 XP to‘plang. Kuniga bir marta.</p><button className="primary-btn full" disabled={state.rewards.some(r=>r.date===today)} onClick={()=>{mutate(s=>claimReward(s));notify('+15 XP mukofoti olindi!')}}>{state.rewards.some(r=>r.date===today)?'Bugungi sovg‘a olindi ✓':'Sovg‘ani olish · +15 XP'}</button></section></div><section className="panel padded"><CardHeading>Umumiy rivojlanish</CardHeading><div className="progress-layout"><Ring value={pct(todayComplete,todayQuests.length)} label="Bugun"/><div className="progress-rows"><div><span>Haftalik reja <b>{weekDone} / {weekPlanned}</b></span><div className="bar"><div style={{width:`${Math.min(100,pct(weekDone,weekPlanned))}%`}}/></div></div><div><span>Oylik reja <b>{monthDone} / {monthPlanned}</b></span><div className="bar violet"><div style={{width:`${Math.min(100,pct(monthDone,monthPlanned))}%`}}/></div></div><div><span>Faollik <b>{streak.current} kun</b></span><div className="bar gold"><div style={{width:`${Math.min(100,streak.current/30*100)}%`}}/></div></div></div></div></section><section><CardHeading>Hayot yo‘nalishlari</CardHeading><div className="category-grid">{categories.map(c=>{const X=categoryIcon[c.id],cXP=skillXP(state,c.id),p=progress(cXP);return <div className="category-card panel" key={c.id}><div className="category-icon" style={{color:c.color,background:c.color+'18'}}><X size={22}/></div><strong>{c.label}</strong><span>{p.level}-daraja · {state.completions.filter(x=>x.category===c.id).length} vazifa</span><div className="bar"><div style={{width:`${p.percent}%`,background:c.color}}/></div><small>{cXP} XP</small></div>})}</div></section></>};
 const questsPage=()=>{const items=state.quests.filter(q=>{const done=completionFor(state,q);const overdue=q.due&&q.due<today&&!done;return (filter==='all'||(filter==='active'&&!done)||(filter==='completed'&&done)||(filter==='overdue'&&overdue))&&(categoryFilter==='all'||q.category===categoryFilter)&&(difficultyFilter==='all'||q.difficulty===difficultyFilter)&&(q.title+' '+q.description).toLowerCase().includes(search.toLowerCase())}).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));return <><SectionTitle subtitle="Vazifalarni yarating, rejalang va XP yig‘ing.">Kvestlar jurnali</SectionTitle><div className="toolbar"><div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Vazifa qidirish..."/></div><button className="primary-btn" onClick={()=>setEditor(blankQuest())}><Plus size={18}/> Yangi kvest</button></div><div className="filter-bar"><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Barcha holatlar</option><option value="active">Faol</option><option value="completed">Bajarilgan</option><option value="overdue">Muddati o‘tgan</option></select><select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}><option value="all">Barcha yo‘nalishlar</option>{categories.map(c=><option value={c.id} key={c.id}>{c.label}</option>)}</select><select value={difficultyFilter} onChange={e=>setDifficultyFilter(e.target.value)}><option value="all">Barcha qiyinliklar</option>{Object.entries(difficultyLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div><section className="panel padded"><CardHeading>{items.length} ta vazifa</CardHeading>{items.length?items.map(q=><QuestRow key={q.id} q={q}/>):<Empty text="Bu filtr bo‘yicha vazifalar yo‘q."/>}</section><p className="muted small">Takrorlanadigan vazifalar har kuni alohida bajariladi. Bir martalik vazifa qayta bajarilganda XP berilmaydi.</p></>};
 const characterPage=()=> <><SectionTitle subtitle="O‘z hayotingizning bosh qahramoni bo‘ling.">Qahramon</SectionTitle><div className="character-banner panel glow"><div className="large-avatar">{state.profile.avatar.startsWith('data:')?<img src={state.profile.avatar} alt="Qahramon"/>:state.profile.avatar}</div><h2>{state.profile.name}</h2><span className="gold-text">{currentTitle}</span><h3>{lvl.level}-DARAJA</h3><div className="bar" style={{maxWidth:400,width:'90%'}}><div style={{width:`${lvl.percent}%`}}/></div><p>{xp} XP · Keyingi darajagacha {lvl.remaining} XP</p><Link href="/settings" className="secondary-btn">Profilni tahrirlash <Edit3 size={15}/></Link></div><div className="stat-grid"><Stat icon={CheckSquare} label="Bajarilgan kvestlar" value={state.completions.length}/><Stat icon={Trophy} label="Yutuqlar" value={achievementCount}/><Stat icon={Flame} label="Joriy seriya" value={streak.current}/><Stat icon={Star} label="Eng uzun seriya" value={streak.longest}/></div><CardHeading>Qahramon ko‘nikmalari <Link className="text-action" href="/skills">Ko‘nikmalar daraxti <ChevronRight size={15}/></Link></CardHeading><div className="category-grid">{categories.map(c=>{const C=categoryIcon[c.id],p=progress(skillXP(state,c.id));return <div className="panel category-card" key={c.id}><C color={c.color}/><b>{c.skill}</b><span>{p.level}-daraja</span><div className="bar"><div style={{width:`${p.percent}%`,background:c.color}}/></div></div>})}</div></>;
 const skillsPage=()=> <><SectionTitle subtitle="Har bir bajarilgan vazifa muayyan ko‘nikmani oshiradi.">Ko‘nikmalar daraxti</SectionTitle><div className="skill-tree">{categories.map((c,i)=>{const C=categoryIcon[c.id],amount=skillXP(state,c.id),p=progress(amount);return <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} key={c.id} className="skill-node panel"><div className="skill-emblem" style={{borderColor:c.color,color:c.color}}><C size={34}/></div><h3>{c.skill}</h3><p>{c.label} · {p.level}-daraja</p><strong style={{color:c.color}}>{amount} XP</strong><div className="bar"><div style={{width:`${p.percent}%`,background:c.color}}/></div><small>{p.current} / {p.need} XP</small><p className="muted small">{state.completions.filter(x=>x.category===c.id).length} ta bajarilgan kvest</p></motion.div>})}</div><section className="panel padded"><CardHeading>Ko‘nikmalar tarixi</CardHeading>{state.transactions.filter(t=>t.category).length?state.transactions.filter(t=>t.category).slice().reverse().slice(0,30).map(t=><div key={t.id} className="history-row"><span>{categories.find(c=>c.id===t.category)?.skill} · {t.reason}</span><b>+{t.amount} XP</b></div>):<Empty text="Ko‘nikmalar tarixi hali bo‘sh."/>}</section></>;
 const prayerPage=()=>{
  const records=state.prayers||[];
  const done=records.filter(p=>p.date===selectedDate&&p.status==='completed').length;
  const qazo=records.filter(p=>p.date===selectedDate&&p.status==='qazo').length;
  const madeup=records.filter(p=>p.date===selectedDate&&p.status==='madeup').length;
  const score=state.transactions.filter(t=>t.reason.startsWith('Namoz:')).reduce((n,t)=>n+t.amount,0);
  const chooseCity=(v:CityKey)=>{
   if(state.prayerConfig){
    if(!confirm('Shahar o‘zgarsa, avtomatik hisoblash bugundan qayta boshlanadi (oldingi qaydlar saqlanadi). Davom etasizmi?'))return;
    mutate(s=>({...s,prayerConfig:{city:v,enabledAt:new Date().toISOString()}}));
   }else setChosenCity(v);
  };
  const todaySchedule=schedule[prayerToday];
  const rows=prayers.map(pr=>{
   const record=records.find(r=>r.date===selectedDate&&r.prayer===pr.id);
   const status=record?.status||'pending';
   const windowTime=prayerWindow(selectedDate,pr.id,schedule);
   const isPastDay=selectedDate<prayerToday;
   const timeExpired=isPastDay||(!!windowTime&&clock>=windowTime.end);
   const mayClaimOnTime=!!windowTime&&!isPastDay&&clock>=windowTime.start&&clock<windowTime.end;
   const isCurrent=selectedDate===prayerToday&&mayClaimOnTime;
   const isUpcoming=!!windowTime&&!timeExpired&&clock<windowTime.start;
   const statusClass=status==='completed'?'performed':status==='madeup'?'madeup':status==='qazo'||timeExpired?'missed':isCurrent?'current':'upcoming';
   const countLabel=status==='completed'?'Vaqtida o‘qilgan':status==='madeup'?'Qazosi o‘qilgan':status==='qazo'?'Qazo':timeExpired?'Vaqti tugagan':isCurrent?'Vaqti kirgan':isUpcoming?'Hali vaqti kirmagan':'Jadval kutilmoqda';
   const timeLabel=status==='completed'?'Namoz qayd etilgan':status==='madeup'?'Qazo ado etilgan':status==='qazo'?'Qazo ro‘yxatida':isCurrent&&windowTime?`Vaqt tugashiga ${countdownText(windowTime.end,clock)}`:isUpcoming&&windowTime?`Vaqt kirishiga ${countdownText(windowTime.start,clock)}`:timeExpired?'O‘qish vaqti tugagan':'Jadval yuklanmoqda';
   return {pr,status,timeExpired,mayClaimOnTime,statusClass,countLabel,timeLabel};
  });
  const missed=rows.filter(r=>r.status==='qazo'||r.status==='madeup'||(r.status==='pending'&&r.timeExpired));
  return <><SectionTitle subtitle="Besh mahal namoz — bir sahifada, aniq va qulay.">Namoz</SectionTitle>
   <section className="panel padded prayer-vertical-section">
    <div className="section-head prayer-compact-heading">
     <div><span className="eyebrow">BESH MAHAL</span><h2>Namoz kundaligi</h2></div>
     <label className="prayer-city-label">Shahar <select aria-label="Namoz shahri" value={activeCity} onChange={e=>chooseCity(e.target.value as CityKey)}>{Object.entries(CITIES).map(([id,c])=><option value={id} key={id}>{c.label}</option>)}</select></label>
    </div>
    <label className="prayer-date-select">Sana <input aria-label="Namoz sanasi" type="date" max={prayerToday} value={selectedDate} onChange={e=>setSelectedDate(e.target.value)}/></label>
    {scheduleError&&<div className="prayer-warning" role="alert">Namoz jadvali olinmadi: {scheduleError}. Vaqt aniqlanmaguncha namozni vaqtida deb belgilab bo‘lmaydi. <button className="secondary-btn" onClick={()=>location.reload()}>Qayta yuklash</button></div>}
    {scheduleLoading&&<p className="muted small">Namoz vaqtlari tekshirilmoqda…</p>}
    {!state.prayerConfig&&<div className="prayer-enable"><span className="muted small">Avtomatik qazo nazorati yoqilgan paytdan boshlab ishlaydi.</span><button type="button" className="primary-btn" disabled={!todaySchedule} onClick={()=>mutate(s=>({...s,prayerConfig:{city:activeCity,enabledAt:new Date().toISOString()}}))}>Avtomatik nazoratni yoqish</button></div>}
    <div className="prayer-long-list">{rows.map(({pr,status,timeExpired,mayClaimOnTime,statusClass,countLabel,timeLabel})=><article className={`prayer-long-card prayer-status-${statusClass}`} key={pr.id}>
      <div className="prayer-long-top"><h3>{pr.label}</h3><span className="prayer-long-status">{countLabel}</span></div>
      <p className="prayer-long-time" aria-live="off">{timeLabel}</p>
      {status==='pending'&&mayClaimOnTime&&<button type="button" className="prayer-long-button" onClick={()=>setSalawatTarget({date:selectedDate,prayer:pr.id,kind:'completed'})}>O‘qidim · +{pr.xp} XP</button>}
      {status==='pending'&&!mayClaimOnTime&&<div className="prayer-long-hint">{timeExpired?'Qazo bo‘limidan belgilashingiz mumkin.':'Vaqti kirganda “O‘qidim” tugmasi paydo bo‘ladi.'}</div>}
      {status==='completed'&&<div className="prayer-long-hint">Vaqtida ado etilgan</div>}
      {status==='qazo'&&<button type="button" className="prayer-long-button prayer-madeup-button" onClick={()=>setSalawatTarget({date:selectedDate,prayer:pr.id,kind:'madeup'})}>Qazosini o‘qidim · +{pr.penalty/2} XP</button>}
      {status==='madeup'&&<div className="prayer-long-hint">Qazo ado etilgan · ballar qayd qilindi</div>}
    </article>)}</div>
    <details className="prayer-collapsible"><summary>Qoidalar va vaqtlar haqida izoh <ChevronRight size={16}/></summary><div className="prayer-collapsible-content"><p>Joriy namoz sariq, vaqtida o‘qilgani yashil, qazo qizil, keyinchalik qazo o‘qilgani ko‘k-binafsha bilan ajratiladi. Vaqtlar tanlangan shahar jadvali bilan hisoblanadi. Bomdod quyosh chiqqunga qadar, boshqa mahalning vaqti navbatdagi belgilangan chegaragacha davom etadi.</p><p>Qazo uchun ikki baravar XP ayiriladi; qazosi keyin o‘qilganda jarimaning yarmi qaytariladi. XP faqat motivatsiya uchun, diniy savob bahosi emas. Salovat oynasini yopish XP bermaydi — faqat Yakunlash hisobga oladi.</p></div></details>
   </section>
   <section className="panel padded prayer-qazo-card"><details className="prayer-collapsible prayer-qazo-details"><summary><span>Qazolar <span className="prayer-count-badge">{missed.length}</span></span><ChevronRight size={18}/></summary>
     <div className="prayer-qazo-content"><p className="muted small">{fmt(selectedDate)} sanasidagi qazo holatlari.</p>
     {missed.length===0?<div className="empty"><p>Bu sana uchun qazo qaydlari yo‘q.</p></div>:missed.map(({pr,status})=><div className="prayer-qazo-row" key={pr.id}>
      <div><strong>{pr.label}</strong><small>{status==='madeup'?'Qazosi ado etilgan':status==='qazo'?'Qazo qayd etilgan':'Vaqti o‘tgan, belgilanmagan'}</small></div>
      {status==='pending'&&<button type="button" className="prayer-action selected-danger" onClick={()=>mutate(s=>setPrayer(s,selectedDate,pr.id,'qazo'))}>Qazo (−{pr.penalty} XP)</button>}
      {status==='qazo'&&<button type="button" className="prayer-action selected-success" onClick={()=>setSalawatTarget({date:selectedDate,prayer:pr.id,kind:'madeup'})}>Qazosini o‘qidim (+{pr.penalty/2} XP)</button>}
      {status==='madeup'&&<span className="prayer-completed-indicator">Qazosi o‘qilgan</span>}
     </div>)}
     </div></details></section>
   <section className="panel padded prayer-details-card"><details className="prayer-collapsible"><summary><span>Natijalar va so‘nggi o‘zgarishlar</span><ChevronRight size={18}/></summary>
     <div className="prayer-details-content"><div className="stat-grid"><Stat icon={Check} label="Ado etilgan" value={`${done}/5`} color="#22C55E"/><Stat icon={Clock} label="Qazo" value={qazo} color="#EF4444"/><Stat icon={Check} label="Qazosi o‘qildi" value={madeup} color="#A855F7"/><Stat icon={Star} label="Namoz XP" value={score} color="#FBBF24"/></div>
     {(state.prayerHistory||[]).length===0?<Empty text="Hozircha o‘zgarishlar yo‘q."/>:(state.prayerHistory||[]).slice(-30).reverse().map(h=><div className="history-row" key={h.id}><span>{fmt(h.date)} · {prayers.find(p=>p.id===h.prayer)?.label} · {h.to==='completed'?'O‘qildi':h.to==='qazo'?'Qazo':h.to==='madeup'?'Qazosi o‘qildi':'Tuzatildi'}</span><b style={{color:h.delta<0?'#EF4444':'#22C55E'}}>{h.delta>0?'+':''}{h.delta} XP</b></div>)}
     </div></details></section>
  </>;
 };
 const achievementPage=()=> <><SectionTitle subtitle="Haqiqiy mehnat bilan yutuqlarni qulfdan chiqaring.">Yutuqlar zali</SectionTitle><div className="stat-grid"><Stat icon={Trophy} label="Ochilgan" value={achievementCount}/><Stat icon={ShieldCheck} label="Qulflangan" value={achievements.length-achievementCount}/><Stat icon={Star} label="Jami XP" value={xp}/><Stat icon={Flame} label="Eng uzun seriya" value={streak.longest}/></div><div className="achievement-grid">{achievements.map((a,i)=><div key={a.name} className={`panel achievement ${unlocked[i]?'unlocked':'locked'}`}><div className="badge-art">{unlocked[i]?a.icon:'🔒'}</div><h3>{a.name}</h3><p>{a.desc}</p><span>{unlocked[i]?'OCHILGAN':'QULFLANGAN'}</span></div>)}</div></>;
 const calendarPage=()=>{const [y,m,d]=selectedDate.split('-').map(Number),first=localDate(new Date(y,m-1,1)),daysInMonth=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+6)%7,week=weekStart(selectedDate),dates=calendarMode==='month'?Array.from({length:Math.ceil((offset+daysInMonth)/7)*7},(_,i)=>dayOffset(first,i-offset)):Array.from({length:7},(_,i)=>dayOffset(week,i));const relevant=state.quests.filter(q=>q.due===selectedDate||q.repeat);return <><SectionTitle subtitle="Rejalashtiring, muddatlarni kuzating va seriyangizni asrang.">Taqvim</SectionTitle><section className="panel padded"><div className="calendar-top"><IconButton onClick={()=>setSelectedDate(calendarMode==='month'?localDate(new Date(y,m-2,Math.min(d,28))):dayOffset(selectedDate,-7))} title="Oldingi"><ChevronLeft/></IconButton><h2>{new Date(y,m-1,1).toLocaleDateString('uz-UZ',{month:'long',year:'numeric'})}</h2><IconButton onClick={()=>setSelectedDate(calendarMode==='month'?localDate(new Date(y,m,Math.min(d,28))):dayOffset(selectedDate,7))} title="Keyingi"><ChevronRight/></IconButton><select value={calendarMode} onChange={e=>setCalendarMode(e.target.value as 'month'|'week')}><option value="month">Oy</option><option value="week">Hafta</option></select></div><div className="calendar-grid">{['Du','Se','Ch','Pa','Ju','Sh','Ya'].map(d=><span className="calendar-weekday" key={d}>{d}</span>)}{dates.map(date=>{const completed=countOn(state,date),planned=state.quests.filter(q=>q.due===date).length;return <button key={date} className={`calendar-day ${date===selectedDate?'selected':''} ${date===today?'today':''} ${date.slice(0,7)!==selectedDate.slice(0,7)?'outside':''}`} onClick={()=>setSelectedDate(date)}><span>{Number(date.slice(8))}</span><div className="dots">{completed>0&&<i className="success-dot"/>}{planned>0&&<i className="cyan-dot"/>}{planned>completed&&date<today&&<i className="red-dot"/>}</div></button>})}</div></section><section className="panel padded"><CardHeading action={<button className="text-action" onClick={()=>setEditor(blankQuest(selectedDate))}><Plus size={15}/> Kvest qo‘shish</button>}>{fmt(selectedDate)} — Reja</CardHeading>{relevant.length?relevant.map(q=><QuestRow q={q} date={selectedDate} key={q.id}/>):<Empty text="Bu sana uchun vazifalar yo‘q."/>}<CardHeading action={<button className="text-action" onClick={()=>setEventEditor(true)}><CalendarPlus size={15}/> Hodisa</button>}>Eslatmalar</CardHeading>{state.events.filter(e=>e.date===selectedDate).map(e=><div className="history-row" key={e.id}><span><b>{e.title}</b> · {e.details}</span><IconButton title="O‘chirish" onClick={()=>{if(confirm('Hodisani o‘chirasizmi?'))mutate(s=>({...s,events:s.events.filter(t=>t.id!==e.id)}))}}><Trash2 size={15}/></IconButton></div>)}</section></>};
 const inventoryPage=()=> <><SectionTitle subtitle="Qo‘lga kiritilgan mukofot va unvonlar to‘plami.">Xazina</SectionTitle><section className="panel padded"><CardHeading>Yig‘ilgan nishonlar</CardHeading><div className="achievement-grid">{achievements.filter((a,i)=>unlocked[i]).length?achievements.filter((a,i)=>unlocked[i]).map(a=><div className="inventory-item" key={a.name}><span>{a.icon}</span><strong>{a.name}</strong></div>):<Empty text="Hozircha nishon yo‘q."/>}</div></section><section className="panel padded"><CardHeading>Ochilgan unvonlar</CardHeading><div className="titles">{titles.map((t,i)=><span className={lvl.level>=1+i*5?'owned':''} key={t}>{lvl.level>=1+i*5?'✦':'🔒'} {t}</span>)}</div></section><section className="panel padded"><CardHeading>Kunlik mukofotlar</CardHeading><p className="muted">{state.rewards.length} ta kunlik sovg‘a · jami {state.rewards.reduce((a,r)=>a+r.xp,0)} XP</p>{state.rewards.slice().reverse().slice(0,20).map(r=><div className="history-row" key={r.date}><span><Gift size={15}/> {fmt(r.date)}</span><b>+{r.xp} XP</b></div>)}</section><section className="panel padded"><CardHeading>Buloq Coins</CardHeading><p className="muted">Virtual tanga tizimi keyingi versiyalar uchun mo‘ljallangan. Hozircha tanga berilmaydi va xarid imkoniyati yo‘q.</p></section></>;
 const statsPage=()=>{const last14=Array.from({length:14},(_,i)=>dayOffset(today,i-13));const totals=categories.map(c=>({name:c.label,n:state.completions.filter(x=>x.category===c.id).length,color:c.color}));const max=Math.max(1,...last14.map(d=>countOn(state,d)));const best=totals.slice().sort((a,b)=>b.n-a.n)[0];const unique=new Set(state.completions.map(c=>c.date));return <><SectionTitle subtitle="Barcha natijalar saqlangan haqiqiy harakatlar asosida hisoblanadi.">Statistika</SectionTitle><div className="stat-grid"><Stat icon={Check} label="Bajarilgan" value={state.completions.length}/><Stat icon={Star} label="XP" value={xp}/><Stat icon={Flame} label="Faol kunlar" value={unique.size}/><Stat icon={Trophy} label="Eng yaxshi seriya" value={streak.longest}/></div><section className="panel padded"><CardHeading>Oxirgi 14 kun — vazifalar</CardHeading><div className="chart">{last14.map(d=>{const n=countOn(state,d);return <div className="chart-col" key={d} title={`${fmt(d)}: ${n} ta`}><b>{n||''}</b><div style={{height:`${Math.max(4,n/max*130)}px`}}/><small>{d.slice(8)}</small></div>})}</div></section><section className="panel padded"><CardHeading>Yo‘nalishlar bo‘yicha</CardHeading>{totals.map(c=><div className="metric" key={c.name}><span>{c.name}<b>{c.n} ta</b></span><div className="bar"><div style={{width:`${pct(c.n,state.completions.length)}%`,background:c.color}}/></div></div>)}<p className="muted small">Eng faol yo‘nalish: {best?.n?best.name:'Hali aniqlanmagan'}</p></section><section className="panel padded"><CardHeading>XP tarixi</CardHeading>{state.transactions.length?state.transactions.slice().reverse().slice(0,40).map(t=><div className="history-row" key={t.id}><span>{fmt(t.date)} · {t.reason}</span><b>{t.amount>0?'+':''}{t.amount} XP</b></div>):<Empty text="Hozircha XP tranzaksiyasi mavjud emas."/>}</section></>};
 const settingsPage=()=> <><SectionTitle subtitle="Profil va ma’lumotlaringizni boshqaring.">Sozlamalar</SectionTitle><section className="panel padded settings-block"><CardHeading>Profil</CardHeading><label>Qahramon ismi<input value={state.profile.name} maxLength={40} onChange={e=>mutate(s=>({...s,profile:{...s.profile,name:e.target.value}}))}/></label><label>Avatar belgisi (emoji)<input value={state.profile.avatar.startsWith('data:')?'':state.profile.avatar} placeholder="🧙" maxLength={5} onChange={e=>mutate(s=>({...s,profile:{...s.profile,avatar:e.target.value}}))}/></label><label>Avatar rasmini yuklash<input type="file" accept="image/*" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2_000_000){notify('Rasm hajmi 2 MB dan kichik bo‘lsin');return}const reader=new FileReader();reader.onload=()=>mutate(s=>({...s,profile:{...s.profile,avatar:String(reader.result)}}));reader.readAsDataURL(f)}}/></label></section><section className="panel padded settings-block"><CardHeading>Ilova imkoniyatlari</CardHeading>{([{key:'sound',title:'Ovozli effektlar'},{key:'animations',title:'Animatsiyalar'},{key:'notifications',title:'Brauzer xabarnomalari'}] as const).map(x=><label className="toggle-line" key={x.key}><span>{x.title}</span><input type="checkbox" checked={state.settings[x.key]} onChange={async e=>{let checked=e.target.checked;if(x.key==='notifications'&&checked){if(!('Notification'in window)){notify('Brauzeringiz bildirishnomalarni qo‘llamaydi');return}checked=(await Notification.requestPermission())==='granted';if(!checked)notify('Bildirishnomaga ruxsat berilmadi')}mutate(s=>({...s,settings:{...s.settings,[x.key]:checked}}))}}/></label>)}<label>Mavzu<select value={state.settings.theme} onChange={e=>mutate(s=>({...s,settings:{...s.settings,theme:e.target.value as 'dark'|'midnight'}}))}><option value="dark">Dark Fantasy</option><option value="midnight">Midnight Blue</option></select></label></section><section className="panel padded settings-block"><CardHeading>Ma’lumotlarni boshqarish</CardHeading><button className="secondary-btn" onClick={signOut}>Hisobdan chiqish</button><p className="muted">Ma’lumotlar Neon PostgreSQL bazasida shaxsiy hisobingizga saqlanadi. Saqlash uchun internet kerak. Vaqti-vaqti bilan JSON zaxira olishni tavsiya qilamiz.</p><button className="secondary-btn" onClick={exportData}><Download size={17}/> JSON zaxira nusxasini olish</button><label className="secondary-btn file-label"><Upload size={17}/> JSON zaxirasini tiklash<input type="file" accept="application/json,.json" onChange={e=>importData(e.target.files?.[0])}/></label><button className="danger-btn" onClick={()=>{if(confirm('DIQQAT: Barcha vazifalar, XP va tarix o‘chadi. Davom etasizmi?')&&confirm('Yana bir bor tasdiqlang: barcha ma’lumot tiklab bo‘lmas tarzda yo‘qoladi.')){setState(createInitial());notify('Barcha ma’lumotlar tozalandi')}}}><Trash2 size={17}/> Barcha rivojlanishni tiklash (reset)</button></section></>;
 if(!ready)return <div className="loading-screen" style={{padding:24,textAlign:'center'}}><Sparkles size={45}/><h2>LIFEQUEST</h2><span>Neon bulut bazasi</span>{checkingSession?<p>Hisob tekshirilmoqda...</p>:<form onSubmit={login} style={{maxWidth:360,width:'100%',display:'grid',gap:12,marginTop:22,textAlign:'left'}}>
 <h3 style={{textAlign:'center'}}>{authMode==='login'?'Hisobga kirish':'Ro‘yxatdan o‘tish'}</h3>
 {authMode==='register'&&<label>Ism<input type="text" value={authName} onChange={e=>setAuthName(e.target.value)} autoComplete="name" minLength={2} maxLength={60} required/></label>}
 <label>Email<input type="email" value={authEmail} onChange={e=>setAuthEmail(e.target.value)} autoComplete="email" placeholder="siz@example.com" required/></label>
 <label>Parol<input type="password" value={authPassword} onChange={e=>setAuthPassword(e.target.value)} autoComplete={authMode==='register'?'new-password':'current-password'} minLength={authMode==='register'?10:1} required placeholder={authMode==='register'?'Kamida 10 ta belgi':'Parolingiz'}/></label>
 <button className="primary-btn" disabled={loggingIn}>{loggingIn?'Tekshirilmoqda...':authMode==='login'?'Kirish':'Ro‘yxatdan o‘tish'}</button>
 <button type="button" className="secondary-btn" onClick={()=>{setAuthMode(authMode==='login'?'register':'login');setError('')}}>{authMode==='login'?'Hisobingiz yo‘qmi? Ro‘yxatdan o‘ting':'Hisobingiz bormi? Kirish'}</button>
 {error&&<p role="alert" style={{color:'#EF4444',fontSize:14}}>{error}</p>}
 </form>}</div>;
 if(error)return <div className="error-screen"><h2>Ma’lumot bazasi xatosi</h2><p>{error}</p><button className="secondary-btn" onClick={exportData}><Download size={16}/> Joriy ma’lumotdan JSON zaxira olish</button><button className="secondary-btn" onClick={()=>location.reload()}>Qayta urinish</button></div>;
 return <div className={`app-shell theme-${state.settings.theme}`}><aside className="sidebar"><Link href="/" className="brand"><span className="brand-mark">✦</span> LIFE<span>QUEST</span></Link><p className="side-caption">SIZNING SARGUZASHTINGIZ</p>{[...nav,...extras].map(({id,label,Icon})=><Link key={id} className={`side-link ${section===id?'active':''}`} href={id==='home'?'/':`/${id}`}><Icon size={19}/>{label}</Link>)}<div className="side-foot"><span>✦ HAQIQIY HAYOT BIRINCHI O‘RINDA</span><p>1.1 · Neon Cloud</p></div></aside><main className="main"><header className="topbar"><Link className="mobile-brand" href="/">✦ LIFE<span>QUEST</span></Link><span className="top-date">{new Date().toLocaleDateString('uz-UZ',{day:'numeric',month:'long',year:'numeric'})}</span><div className="top-actions"><span className="level-pill"><Star size={14}/>{xp} XP</span><button className="icon-btn notification-button" onClick={()=>setShowNotifications(true)} aria-label="Bildirishnomalar"><Bell size={19}/></button><Link className="mini-avatar" href="/character">{state.profile.avatar.startsWith('data:')?<img src={state.profile.avatar} alt="Profil"/>:state.profile.avatar}</Link></div></header>{saveStatus!=='saved'&&<div className={`save-banner ${saveStatus}`} role="status"><CloudUpload size={17}/>{saveStatus==='saving'?'Neon bazasiga saqlanmoqda…':`Saqlanmadi: ${saveError}`} {saveStatus==='error'&&<button onClick={retrySave}>Qayta saqlash</button>}</div>}<div className="page-body">{section==='home'?dashboard():section==='quests'?questsPage():section==='character'?characterPage():section==='prayer'?prayerPage():section==='skills'?skillsPage():section==='achievements'?achievementPage():section==='calendar'?calendarPage():section==='inventory'?inventoryPage():section==='statistics'?statsPage():section==='settings'?settingsPage():<Empty text="Sahifa topilmadi"/>}</div></main><nav className="bottom-nav">{nav.map(({id,label,Icon})=><Link href={id==='home'?'/':`/${id}`} className={section===id?'active':''} key={id}><Icon size={22}/><span>{label}</span></Link>)}</nav><AnimatePresence>{salawatTarget&&<motion.div className="overlay" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} role="presentation" onClick={()=>setSalawatTarget(null)}><motion.div className="salawat-modal panel" role="dialog" aria-modal="true" aria-labelledby="salawat-title" initial={{opacity:0,y:22,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:12,scale:.98}} onClick={e=>e.stopPropagation()}>
    <div className="salawat-modal-head"><div><span className="eyebrow">SALOVAT</span><h2 id="salawat-title">{prayers.find(p=>p.id===salawatTarget.prayer)?.label} — {salawatByPrayer[salawatTarget.prayer].title}</h2></div><IconButton title="Oynani yopish" onClick={()=>setSalawatTarget(null)}><X size={20}/></IconButton></div>
    <p className="salawat-arabic" lang="ar" dir="rtl">{salawatByPrayer[salawatTarget.prayer].arabic}</p>
    <p className="salawat-latin">{salawatByPrayer[salawatTarget.prayer].latin}</p>
    <p className="salawat-meaning">{salawatByPrayer[salawatTarget.prayer].meaning}</p>
    <p className="salawat-notice">Namoz hali qayd etilmadi. Yakunlash bosilgandan keyingina {salawatTarget.kind==='madeup'?'qazosi ado etilgan':'vaqtida o‘qilgan'} deb saqlanadi.</p>
    <div className="salawat-modal-actions"><button type="button" className="secondary-btn" onClick={()=>setSalawatTarget(null)}>Bekor qilish</button><button type="button" className="primary-btn" onClick={()=>{const target=salawatTarget;if(!target)return;const current=state.prayers.find(r=>r.date===target.date&&r.prayer===target.prayer)?.status||'pending';if(target.kind==='completed'){const w=prayerWindow(target.date,target.prayer,schedule);if(current!=='pending'||!w||Date.now()<w.start||Date.now()>=w.end){notify('Namoz vaqti tugagan yoki holati o‘zgargan. Qazo bo‘limini tekshiring.');setSalawatTarget(null);return}}else if(current!=='qazo'){notify('Qazo holati o‘zgargan. Sahifani tekshiring.');setSalawatTarget(null);return}mutate(s=>setPrayer(s,target.date,target.prayer,target.kind));setSalawatTarget(null);notify('Namoz qayd etildi')}}>Yakunlash</button></div>
   </motion.div></motion.div>}{editor&&<motion.div className="overlay" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={()=>setEditor(null)}><motion.form initial={{scale:.94,y:25}} animate={{scale:1,y:0}} exit={{scale:.94,y:25}} className="modal panel" onClick={e=>e.stopPropagation()} onSubmit={e=>{e.preventDefault();saveQuest(editor)}}><div className="section-head"><h2>{state.quests.some(q=>q.id===editor.id)?'Kvestni tahrirlash':'Yangi kvest'}</h2><IconButton title="Yopish" onClick={()=>setEditor(null)}><X size={19}/></IconButton></div><label>Vazifa nomi<input required value={editor.title} maxLength={140} onChange={e=>setEditor({...editor,title:e.target.value})} placeholder="Masalan: 30 daqiqa kitob o‘qish"/></label><label>Tavsif<textarea rows={3} value={editor.description} onChange={e=>setEditor({...editor,description:e.target.value})} placeholder="Batafsil reja..."/></label><div className="form-grid"><label>Kvest turi<select value={editor.kind} onChange={e=>setEditor({...editor,kind:e.target.value as QuestKind})}>{Object.entries(kindLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Yo‘nalish<select value={editor.category} onChange={e=>setEditor({...editor,category:e.target.value as Category})}>{categories.map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label><label>Qiyinlik<select value={editor.difficulty} onChange={e=>{const difficulty=e.target.value as Difficulty;setEditor({...editor,difficulty,xp:xpByDifficulty[difficulty]})}}>{Object.entries(difficultyLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Muhimlik<select value={editor.priority} onChange={e=>setEditor({...editor,priority:e.target.value as Priority})}>{Object.entries(priorityLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Muddat<input type="date" value={editor.due} onChange={e=>setEditor({...editor,due:e.target.value})}/></label><label>XP mukofoti<input type="number" min="0" max="1000" value={editor.xp} onChange={e=>setEditor({...editor,xp:Math.max(0,Math.min(1000,Number(e.target.value)||0))})}/></label></div><label className="toggle-line">Har kuni takrorlash <input type="checkbox" checked={editor.repeat} onChange={e=>setEditor({...editor,repeat:e.target.checked})}/></label><button className="primary-btn full" type="submit"><Save size={18}/> Saqlash</button></motion.form></motion.div>}{eventEditor&&<motion.div className="overlay" initial={{opacity:0}} animate={{opacity:1}} onClick={()=>setEventEditor(false)}><form className="modal panel" onClick={e=>e.stopPropagation()} onSubmit={e=>{e.preventDefault();if(!eventTitle.trim())return;mutate(s=>({...s,events:[...s.events,{id:uid(),date:selectedDate,title:eventTitle,details:eventDetails}]}));setEventEditor(false);setEventTitle('');setEventDetails('')}}><CardHeading>Yangi hodisa</CardHeading><label>Nomi<input required value={eventTitle} onChange={e=>setEventTitle(e.target.value)}/></label><label>Izoh<textarea value={eventDetails} onChange={e=>setEventDetails(e.target.value)}/></label><button className="primary-btn full" type="submit">Qo‘shish</button><button type="button" className="secondary-btn full" onClick={()=>setEventEditor(false)}>Bekor qilish</button></form></motion.div>}{showNotifications&&<motion.div className="overlay" initial={{opacity:0}} animate={{opacity:1}} onClick={()=>setShowNotifications(false)}><div className="modal panel" onClick={e=>e.stopPropagation()}><CardHeading action={<IconButton title="Yopish" onClick={()=>setShowNotifications(false)}><X size={18}/></IconButton>}>Xabarnomalar</CardHeading>{state.quests.filter(q=>q.due&&q.due<today&&!completionFor(state,q)).map(q=><div key={q.id} className="history-row"><span>⚠️ {q.title} — muddati o‘tgan</span></div>)}{state.quests.filter(q=>q.due===dayOffset(today,1)&&!completionFor(state,q)).map(q=><div key={q.id} className="history-row">⏰ Ertaga: {q.title}</div>)}{state.quests.filter(q=>q.due&&q.due<=dayOffset(today,1)&&!completionFor(state,q)).length===0&&<Empty text="Hozircha yangi eslatma yo‘q"/>}</div></motion.div>}</AnimatePresence>{toast&&<div className="toast"><Sparkles size={18}/>{toast}</div>}</div>
}
function levelFrom(xp:number){return progress(xp).level}
